public class Main {
    static abstract class 小猫 {
        abstract String 叫声();
    }

    static class 橘猫 extends 小猫 {
        @Override
        String 叫声() {
            return "{v1}";
        }
    }

    static class 狸花猫 extends 小猫 {
        @Override
        String 叫声() {
            return "{v2}";
        }
    }

    static class 三花猫 extends 小猫 {
        @Override
        String 叫声() {
            return "{v3}";
        }
    }

    static 小猫 领养一只(String 花色) {
        if (花色.equals("橘")) {
            return new 橘猫();
        }
        if (花色.equals("狸花")) {
            return new 狸花猫();
        }
        return new 三花猫();
    }

    public static void main(String[] args) {
        for (String 花色 : new String[]{"橘", "狸花", "{f}"}) {
            System.out.println(花色 + " -> " + 领养一只(花色).叫声());
        }
    }
}
